1	package nettrace
2	
3	import (
4		"fmt"
5		"go/ast"
6		"go/parser"
7		"go/token"
8		"os"
9		"strconv"
10		"strings"
11		"testing"
12	)
13	
14	// The trace sends its probes itself, over ICMP and UDP sockets. It must never
15	// start a child process (traceroute, ping) nor replace the process image, on
16	// any platform. The guard reads every .go file of the package whatever its
17	// build constraints (go/parser does not evaluate them), so a file that only
18	// builds on another OS is covered too.
19	
20	// bannedImports are packages that must not be imported at all.
21	var bannedImports = map[string]bool{
22		"os/exec":                  true,
23		"golang.org/x/sys/execabs": true,
24		// Windows services can launch processes.
25		"golang.org/x/sys/windows/svc":     true,
26		"golang.org/x/sys/windows/svc/mgr": true,
27	}
28	
29	// dotWatched are packages that must not be dot-imported: a dot-import hides
30	// the package name the selector check relies on.
31	var dotWatched = map[string]bool{
32		"os":                    true,
33		"syscall":               true,
34		"os/exec":               true,
35		"golang.org/x/sys/unix": true,
36		winPath:                 true,
37	}
38	
39	// winPath is the Windows system-call package. The Windows engine may use it
40	// to load iphlpapi.dll only (see the rules in guardSource).
41	const winPath = "golang.org/x/sys/windows"
42	
43	// winDLL is the one DLL the Windows engine may load.
44	const winDLL = "iphlpapi.dll"
45	
46	// winProcs is the exact, case-sensitive list of entry points NewProc may
47	// resolve: the IP Helper ICMP echo API, nothing else.
48	var winProcs = map[string]bool{
49		"IcmpCreateFile": true, "Icmp6CreateFile": true,
50		"IcmpSendEcho2": true, "Icmp6SendEcho2": true,
51		"IcmpCloseHandle": true,
52	}
53	
54	// bannedSymbols maps an import path to the process-launching symbols it must
55	// not expose here, called or not (`f := os.StartProcess` is caught too). The
56	// socket symbols the engine needs (Recvmsg, Setsockopt...) stay allowed.
57	var bannedSymbols = map[string]map[string]bool{
58		"os": {"StartProcess": true},
59		"syscall": {
60			"StartProcess": true, "ForkExec": true, "Exec": true,
61			"Syscall": true, "Syscall6": true, "RawSyscall": true, "RawSyscall6": true,
62			"SyscallN": true, "Syscall9": true, "Syscall12": true, "Syscall15": true, "Syscall18": true,
63			"CreateProcess": true, "CreateProcessAsUser": true,
64			"LoadLibrary": true, "GetProcAddress": true,
65			"LoadDLL": true, "MustLoadDLL": true, "NewLazyDLL": true,
66			"LazyDLL": true, "DLL": true, "LazyProc": true, "Proc": true,
67		},
68		"golang.org/x/sys/unix": {
69			"Exec":    true,
70			"Syscall": true, "Syscall6": true, "RawSyscall": true, "RawSyscall6": true,
71			"Syscall9": true, "RawSyscall9": true, "SyscallNoError": true, "RawSyscallNoError": true,
72		},
73		winPath: {
74			"CreateProcess": true, "CreateProcessAsUser": true, "ShellExecute": true,
75			"Syscall": true, "Syscall6": true, "Syscall9": true, "Syscall12": true,
76			"Syscall15": true, "Syscall18": true, "SyscallN": true,
77			"LoadLibrary": true, "LoadLibraryEx": true,
78			"GetProcAddress": true, "GetProcAddressByOrdinal": true,
79			"LoadDLL": true, "MustLoadDLL": true, "NewLazyDLL": true,
80			// Naming these types would build a DLL handle without NewLazySystemDLL;
81			// NewProc and Call on the value NewLazySystemDLL returns need no name.
82			"LazyDLL": true, "DLL": true, "LazyProc": true, "Proc": true,
83			// Services start executables.
84			"CreateService": true, "StartService": true, "OpenSCManager": true,
85		},
86	}
87	
88	// isStringLit reports whether e is a string literal and returns its value.
89	func isStringLit(e ast.Expr) (string, bool) {
90		lit, ok := e.(*ast.BasicLit)
91		if !ok || lit.Kind != token.STRING {
92			return "", false
93		}
94		v, err := strconv.Unquote(lit.Value)
95		return v, err == nil
96	}
97	
98	// winCallOffence checks the two Windows loading rules on a call in a file
99	// that imports x/sys/windows: NewLazySystemDLL takes the literal "iphlpapi.dll"
100	// only, and NewProc takes a literal from winProcs only. It returns a message
101	// or "". One call is one offence at most.
102	func winCallOffence(fset *token.FileSet, call *ast.CallExpr, winNames map[string]bool) string {
103		sel, ok := call.Fun.(*ast.SelectorExpr)
104		if !ok || len(call.Args) != 1 {
105			return ""
106		}
107		lit, isLit := isStringLit(call.Args[0])
108		switch sel.Sel.Name {
109		case "NewLazySystemDLL":
110			id, ok := sel.X.(*ast.Ident)
111			if !ok || !winNames[id.Name] {
112				return ""
113			}
114			if !isLit || lit != winDLL {
115				return fmt.Sprintf("%s: NewLazySystemDLL may load only the literal %q", fset.Position(call.Pos()), winDLL)
116			}
117		case "NewProc":
118			if !isLit || !winProcs[lit] {
119				return fmt.Sprintf("%s: NewProc may resolve only the ICMP echo entry points by literal name", fset.Position(call.Pos()))
120			}
121		}
122		return ""
123	}
124	
125	// dllFields are the exported fields of a DLL handle that choose what gets
126	// loaded (Name, System) or what was loaded (Dll). Writing them after
127	// NewLazySystemDLL would turn the iphlpapi.dll rule into a no-op.
128	var dllFields = map[string]bool{"Name": true, "System": true, "Dll": true}
129	
130	func unparen(e ast.Expr) ast.Expr {
131		for {
132			p, ok := e.(*ast.ParenExpr)
133			if !ok {
134				return e
135			}
136			e = p.X
137		}
138	}
139	
140	// writtenTargets returns the expressions n writes to or takes the address of:
141	// assignment targets (also op-assign), ++/--, range key/value, and &x.
142	func writtenTargets(n ast.Node) []ast.Expr {
143		switch s := n.(type) {
144		case *ast.AssignStmt:
145			return s.Lhs
146		case *ast.IncDecStmt:
147			return []ast.Expr{s.X}
148		case *ast.RangeStmt:
149			return []ast.Expr{s.Key, s.Value}
150		case *ast.UnaryExpr:
151			if s.Op == token.AND {
152				return []ast.Expr{s.X}
153			}
154		}
155		return nil
156	}
157	
158	// guardSource returns one message per offence in src ("name:line: ...").
159	func guardSource(fset *token.FileSet, name string, src any) ([]string, error) {
160		file, err := parser.ParseFile(fset, name, src, parser.SkipObjectResolution)
161		if err != nil {
162			return nil, err
163		}
164		var out []string
165		local := map[string]string{}  // local package name -> import path
166		winNames := map[string]bool{} // local names of x/sys/windows
167		importsSys := false           // syscall or x/sys/windows: the NewProc rules apply
168		for _, imp := range file.Imports {
169			path, _ := strconv.Unquote(imp.Path.Value)
170			if bannedImports[path] {
171				out = append(out, fmt.Sprintf("%s: import of %s", fset.Position(imp.Pos()), path))
172			}
173			if imp.Name != nil && imp.Name.Name == "." && dotWatched[path] {
174				out = append(out, fmt.Sprintf("%s: dot-import of %s", fset.Position(imp.Pos()), path))
175			}
176			if path == winPath || path == "syscall" {
177				importsSys = true
178			}
179			if _, watched := bannedSymbols[path]; !watched {
180				continue
181			}
182			n := path[strings.LastIndex(path, "/")+1:]
183			if imp.Name != nil {
184				n = imp.Name.Name
185			}
186			local[n] = path
187			if path == winPath {
188				winNames[n] = true
189			}
190		}
191		// calledLoad holds the bare windows.NewLazySystemDLL selectors that are the
192		// function of a call; any other reference (value, parentheses) is refused.
193		// calledProc does the same for the NewProc selectors.
194		calledLoad := map[*ast.SelectorExpr]bool{}
195		calledProc := map[*ast.SelectorExpr]bool{}
196		ast.Inspect(file, func(n ast.Node) bool {
197			if importsSys {
198				for _, target := range writtenTargets(n) {
199					if sel, ok := unparen(target).(*ast.SelectorExpr); ok && dllFields[sel.Sel.Name] {
200						out = append(out, fmt.Sprintf("%s: writing the %s field could redirect a DLL load", fset.Position(sel.Pos()), sel.Sel.Name))
201					}
202				}
203			}
204			if call, ok := n.(*ast.CallExpr); ok && importsSys {
205				if sel, ok := call.Fun.(*ast.SelectorExpr); ok {
206					switch sel.Sel.Name {
207					case "NewLazySystemDLL":
208						calledLoad[sel] = true
209					case "NewProc":
210						calledProc[sel] = true
211					}
212				}
213				if msg := winCallOffence(fset, call, winNames); msg != "" {
214					out = append(out, msg)
215				}
216				return true
217			}
218			sel, ok := n.(*ast.SelectorExpr)
219			if !ok {
220				return true
221			}
222			if importsSys && sel.Sel.Name == "NewProc" && !calledProc[sel] {
223				out = append(out, fmt.Sprintf("%s: NewProc must be called directly, not used as a value", fset.Position(sel.Pos())))
224			}
225			id, ok := sel.X.(*ast.Ident)
226			if !ok {
227				return true
228			}
229			if winNames[id.Name] && sel.Sel.Name == "NewLazySystemDLL" && !calledLoad[sel] {
230				out = append(out, fmt.Sprintf("%s: %s.NewLazySystemDLL must be called directly, not used as a value", fset.Position(sel.Pos()), id.Name))
231			}
232			if path, ok := local[id.Name]; ok && bannedSymbols[path][sel.Sel.Name] {
233				out = append(out, fmt.Sprintf("%s: use of %s.%s", fset.Position(sel.Pos()), id.Name, sel.Sel.Name))
234			}
235			return true
236		})
237		return out, nil
238	}
