319	func TestPackageNeverStartsAProcess(t *testing.T) {
320		entries, err := os.ReadDir(".")
321		if err != nil {
322			t.Fatal(err)
323		}
324		fset := token.NewFileSet()
325		files := 0
326		for _, e := range entries {
327			if e.IsDir() || !strings.HasSuffix(e.Name(), ".go") {
328				continue
329			}
330			src, err := os.ReadFile(e.Name())
331			if err != nil {
332				t.Fatal(err)
333			}
334			files++
335			offences, err := guardSource(fset, e.Name(), src)
336			if err != nil {
337				t.Errorf("%s: %v", e.Name(), err)
338				continue
339			}
340			for _, o := range offences {
341				t.Error(o + ": the trace must not start or exec a process")
342			}
343		}
344		if files == 0 {
345			t.Error("the scan saw no Go file: the guard would pass vacuously")
346		}
347	}

